--select * from @tabpro 

--relatório de vendas detalhado no período de 01.01.2018 a 31.12.2022
--•	Data da venda
--LICENCIADOR PRODUTOS
--PERSONAGEM PRODUTOS
--PRODUTO PRODUTOS
--DESC_PRODUTO PRODUTOS
--•	Nº da NF/Cupom de venda
-- QTDE ITENS VENDIDO
--•	Valor da venda
--•	Valor do ICMS - ESQUECE

select p.ERP_DESC_LICENCIADO,YEAR(A.DATA_VENDA) AS ANO,count(*) as qty

from LOJA_VENDA a
inner join LOJA_VENDA_PRODUTO b 
	on b.DATA_VENDA=a.DATA_VENDA and b.CODIGO_FILIAL=a.CODIGO_FILIAL and b.TICKET=a.TICKET
inner join PRODUTOS p on p.produto = b.PRODUTO
where a.DATA_VENDA between '20180101' and '20221231'
AND P.ERP_LICENCIADO='LOONEY TUNES'                                      
and a.VALOR_PAGO>0 and a.VALOR_CANCELADO=0
and b.PRODUTO in (select produto from @tabpro)
--group by p.ERP_DESC_LICENCIADO,YEAR(A.DATA_VENDA)




